(function () {
  function setup() {
    const wrapper = document.querySelector(".heritage-curve-wrapper");
    if (!wrapper) return;

    const path = wrapper.querySelector("#heritage-path");
    const dots = Array.from(wrapper.querySelectorAll(".timeline-dot"));
    const labelsContainer = wrapper.querySelector(".heritage-labels");
    const labels = labelsContainer ? Array.from(labelsContainer.children) : [];

    if (!path || !dots.length) return;

    const totalLength = path.getTotalLength();
    path.style.strokeDasharray = String(totalLength);
    path.style.strokeDashoffset = String(totalLength);

    // Work out how far along the path (0-1) each dot sits, by sampling
    // the path and finding the closest point to each dot's cx/cy.
    const dotProgress = dots.map(function (dot) {
      const cx = parseFloat(dot.getAttribute("cx"));
      const cy = parseFloat(dot.getAttribute("cy"));
      let closestLength = 0;
      let closestDist = Infinity;
      const samples = 400;
      for (let i = 0; i <= samples; i++) {
        const len = (totalLength * i) / samples;
        const pt = path.getPointAtLength(len);
        const dist = (pt.x - cx) * (pt.x - cx) + (pt.y - cy) * (pt.y - cy);
        if (dist < closestDist) {
          closestDist = dist;
          closestLength = len;
        }
      }
      return closestLength / totalLength;
    });

    let targetProgress = 0;
    let renderedProgress = 0;

    function computeTargetProgress() {
      const rect = wrapper.getBoundingClientRect();
      const vh = window.innerHeight;
      // progress: 0 when the wrapper's top is just entering the viewport,
      // 1 once the wrapper has scrolled most of the way past.
      const start = vh * 0.85;
      const end = -(rect.height - vh * 0.35);
      const progress = (start - rect.top) / (start - end);
      return Math.min(Math.max(progress, 0), 1);
    }

    function render() {
      // Ease the rendered value toward the scroll-derived target every
      // animation frame, instead of snapping straight to it on each
      // scroll event — this is what keeps the line gliding smoothly
      // even when the browser delivers scroll events in bursts.
      renderedProgress += (targetProgress - renderedProgress) * 0.12;
      if (Math.abs(targetProgress - renderedProgress) < 0.0005) {
        renderedProgress = targetProgress;
      }

      path.style.strokeDashoffset = String(totalLength * (1 - renderedProgress));

      dots.forEach(function (dot, i) {
        const reached = renderedProgress >= dotProgress[i] - 0.01;
        dot.classList.toggle("is-visible", reached);
        if (labels[i]) labels[i].classList.toggle("is-visible", reached);
      });

      requestAnimationFrame(render);
    }

    function onScrollOrResize() {
      targetProgress = computeTargetProgress();
    }

    window.addEventListener("scroll", onScrollOrResize, { passive: true });
    window.addEventListener("resize", onScrollOrResize);

    onScrollOrResize();
    renderedProgress = targetProgress; // reflect scroll position instantly on load, no glide-in
    render();
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", setup);
  } else {
    setup();
  }
})();
